{
  "name": "ExamGen 10 - Tiếng Anh",
  "description": "Ứng dụng hỗ trợ giáo viên Tiếng Anh THCS tạo đề thi tuyển sinh lớp 10 chuẩn GDPT 2018 sử dụng Google Gemini AI."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum AppStep {
  UPLOAD = 1,
  MATRIX = 2,
  GENERATE = 3,
  PREVIEW = 4
}

export enum QuestionLevel {
  NB = 'Nhận biết',
  TH = 'Thông hiểu',
  VD = 'Vận dụng',
  VDC = 'Vận dụng cao'
}

export interface Question {
  id: string;
  partName: string; // e.g., "Phát âm", "Reading"
  type: 'multiple-choice' | 'constructed-response' | 'essay';
  content: string;
  options?: string[]; // For multiple choice
  correctAnswer?: string; // For teacher reference
  level: QuestionLevel;
}

export interface ExamSection {
  title: string;
  questions: Question[];
  totalPoints: number;
}

export interface ExamData {
  title: string;
  subtitle: string;
  duration: number; // minutes
  sections: ExamSection[];
  analysis?: {
    difficulty: string;
    structureSummary: string;
    cefrLevel: string;
  };
}

export interface MatrixData {
  rawText: string;
  parsed?: any;
}

import { GoogleGenAI, Type } from "@google/genai";
import { ExamData, QuestionLevel } from "../types";

// Initialize Gemini Client
const getClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) throw new Error("API Key not found");
  return new GoogleGenAI({ apiKey });
};

const MODEL_NAME = "gemini-2.5-flash-latest"; // Fast and capable for text tasks

/**
 * Step 1: Analyze the uploaded exam text
 */
export const analyzeExamFile = async (fileContent: string): Promise<{ difficulty: string; structureSummary: string; cefrLevel: string }> => {
  const client = getClient();

  const prompt = `
    Bạn là một chuyên gia giáo dục Tiếng Anh tại Việt Nam. 
    Hãy phân tích nội dung đề thi dưới đây (được trích xuất từ file).

    Nhiệm vụ:
    1. Xác định mức độ khó tổng thể (Dễ/Trung bình/Khá/Khó).
    2. Tóm tắt cấu trúc (Các phần chính, số lượng câu).
    3. Đánh giá khung năng lực ngoại ngữ (CEFR Level ước lượng, ví dụ A2, B1).

    Trả về định dạng JSON:
    {
      "difficulty": "string",
      "structureSummary": "string",
      "cefrLevel": "string"
    }

    Nội dung đề thi:
    ${fileContent.substring(0, 10000)} 
  `;

  try {
    const response = await client.models.generateContent({
      model: MODEL_NAME,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            difficulty: { type: Type.STRING },
            structureSummary: { type: Type.STRING },
            cefrLevel: { type: Type.STRING },
          },
        }
      }
    });

    if (response.text) {
      return JSON.parse(response.text);
    }
    throw new Error("No response text");
  } catch (error) {
    console.error("Error analyzing exam:", error);
    return {
      difficulty: "Chưa xác định",
      structureSummary: "Không thể phân tích cấu trúc",
      cefrLevel: "N/A"
    };
  }
};

/**
 * Step 3: Generate the full exam based on matrix and analysis
 */
export const generateFullExam = async (
  matrixText: string,
  analysisData: { difficulty: string; cefrLevel: string }
): Promise<ExamData> => {
  const client = getClient();

  const systemInstruction = `
    Bạn là chuyên gia soạn đề thi Tiếng Anh tuyển sinh vào lớp 10 THPT tại Việt Nam.
    Bạn nắm vững chương trình GDPT 2018 (sách Global Success, Friends Plus, iLearn Smart World).

    Yêu cầu quan trọng:
    - Nội dung: 85% kiến thức lớp 9, 10% lớp 8, 5% nâng cao.
    - Không trùng lặp câu hỏi cũ.
    - Ngôn ngữ: Tiếng Anh chuẩn mực.
    - Đảm bảo tính phân hóa.
  `;

  const prompt = `
    Hãy tạo một đề thi hoàn chỉnh dựa trên MA TRẬN và ĐỘ KHÓ sau đây.

    1. ĐỘ KHÓ MỤC TIÊU: ${analysisData.difficulty} (Tương đương ${analysisData.cefrLevel}).

    2. MA TRẬN ĐỀ THI (Cấu trúc bắt buộc):
    ${matrixText}

    3. YÊU CẦU ĐẦU RA (JSON):
    Hãy trả về JSON cấu trúc như sau:
    {
      "title": "KỲ THI TUYỂN SINH VÀO LỚP 10 THPT",
      "subtitle": "MÔN: TIẾNG ANH - NĂM HỌC 2024-2025",
      "duration": 60,
      "sections": [
        {
          "title": "Tên phần (Ví dụ: PHONETICS, GRAMMAR...)",
          "totalPoints": 0.0,
          "questions": [
            {
              "id": "1",
              "partName": "Phát âm",
              "type": "multiple-choice" (hoặc "constructed-response"),
              "content": "Nội dung câu hỏi...",
              "options": ["A. ...", "B. ...", "C. ...", "D. ..."] (nếu trắc nghiệm),
              "correctAnswer": "Đáp án đúng",
              "level": "Nhận biết" (hoặc "Thông hiểu", "Vận dụng", "Vận dụng cao")
            }
          ]
        }
      ]
    }
  `;

  try {
    const response = await client.models.generateContent({
      model: MODEL_NAME, // Using flash-latest as specified in guidelines for Gemini 2.0/1.5 equivalents
      contents: prompt,
      config: {
        systemInstruction: systemInstruction,
        responseMimeType: "application/json",
        // Using a simpler schema definition or raw JSON parsing for complex nested structures to avoid schema limit issues
        // Let's try raw JSON prompting which Gemini handles very well for exams.
      }
    });

    if (response.text) {
        return JSON.parse(response.text) as ExamData;
    }
    throw new Error("Failed to generate exam content");
  } catch (error) {
    console.error("Generation Error:", error);
    // Return a fallback mock if API fails heavily (for demo resilience), but typically we throw
    throw error;
  }
};

