import { GoogleGenAI, Type } from "@google/genai";
import { ExamData, AnalysisResult } from "../types";

// Initialize Gemini Client
const getClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) throw new Error("API Key not found");
  return new GoogleGenAI({ apiKey });
};

const MODEL_NAME = "gemini-3-flash-preview"; 

// Helper to clean JSON string from Markdown formatting
const cleanJsonString = (str: string) => {
  if (!str) return "";
  let cleaned = str.replace(/^```json\s*/, "").replace(/^```\s*/, "").replace(/\s*```$/, "");
  return cleaned.trim();
};

/**
 * Step 1: Analyze the uploaded exam text
 */
export const analyzeExamFile = async (fileContent: string): Promise<AnalysisResult> => {
  const client = getClient();

  const prompt = `
    Bạn là một chuyên gia giáo dục Tiếng Anh tại Việt Nam. 
    Hãy phân tích nội dung đề thi dưới đây (được trích xuất từ file).

    Nhiệm vụ:
    1. Xác định mức độ khó tổng thể (Dễ/Trung bình/Khá/Khó).
    2. Tóm tắt cấu trúc (Các phần chính, số lượng câu).
    3. Đánh giá khung năng lực ngoại ngữ (CEFR Level ước lượng, ví dụ A2, B1).
    4. PHÂN TÍCH RIÊNG PHẦN ĐỌC HIỂU (READING):
       - Tính toán ước lượng số lượng từ (word count) trung bình của các đoạn văn/bài đọc có trong đề.
       - Mô tả ngắn gọn độ phức tạp của ngữ liệu đọc (ví dụ: Chủ đề quen thuộc, câu đơn giản hay văn bản học thuật, câu ghép phức tạp).

    Trả về định dạng JSON:
    {
      "difficulty": "string",
      "structureSummary": "string",
      "cefrLevel": "string",
      "readingStats": {
        "avgWordCount": number, // Ví dụ: 150
        "difficultyDesc": "string" // Ví dụ: "Văn bản thông tin, từ vựng chủ đề môi trường, câu phức trung bình"
      }
    }

    Nội dung đề thi:
    ${fileContent.substring(0, 15000)} 
  `;

  try {
    const response = await client.models.generateContent({
      model: MODEL_NAME,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
      }
    });

    if (response.text) {
      const cleanedText = cleanJsonString(response.text);
      return JSON.parse(cleanedText);
    }
    throw new Error("No response text");
  } catch (error) {
    console.error("Error analyzing exam:", error);
    return {
      difficulty: "Chưa xác định",
      structureSummary: "Không thể phân tích cấu trúc",
      cefrLevel: "N/A",
      readingStats: {
        avgWordCount: 150, // Default fallback
        difficultyDesc: "Trung bình"
      }
    };
  }
};

/**
 * Step 3: Generate the full exam based on matrix and analysis
 */
export const generateFullExam = async (
  matrixText: string,
  analysisData: AnalysisResult
): Promise<ExamData> => {
  const client = getClient();

  const systemInstruction = `
    Bạn là chuyên gia soạn đề thi Tiếng Anh tuyển sinh vào lớp 10 THPT tại Việt Nam.
    Bạn nắm vững chương trình GDPT 2018 (Sách Global Success, Friends Plus...).

    Yêu cầu quan trọng:
    - Nội dung: 85% kiến thức lớp 9, 10% lớp 8, 5% nâng cao.
    - Không trùng lặp câu hỏi cũ.
    - Ngôn ngữ: Tiếng Anh chuẩn mực.
  `;

  const prompt = `
    Hãy tạo một đề thi hoàn chỉnh dựa trên MA TRẬN và CÁC RÀNG BUỘC sau đây.

    1. ĐỘ KHÓ MỤC TIÊU: ${analysisData.difficulty} (Tương đương ${analysisData.cefrLevel}).

    2. RÀNG BUỘC PHẦN ĐỌC HIỂU (READING) - BẮT BUỘC TUÂN THỦ:
       - ĐỘ DÀI: Các bài đọc phải có độ dài khoảng ${analysisData.readingStats.avgWordCount} từ/bài (Chấp nhận sai số ±10%). 
       - NGỮ LIỆU: Sử dụng ngữ liệu có độ khó tương đương mô tả: "${analysisData.readingStats.difficultyDesc}".
       - CHỦ ĐỀ: Nằm trong chương trình SGK Tiếng Anh 9 mới (Global Success, Friends Plus...).
       - LƯU Ý: Nếu ma trận yêu cầu 2 bài đọc, cả 2 bài phải tuân thủ độ dài này.

    3. MA TRẬN ĐỀ THI:
    ${matrixText}

    4. YÊU CẦU ĐẦU RA (JSON):
    Trả về JSON cấu trúc như sau (KHÔNG thêm markdown block):
    {
      "title": "KỲ THI TUYỂN SINH VÀO LỚP 10 THPT",
      "subtitle": "MÔN: TIẾNG ANH - NĂM HỌC 2024-2025",
      "duration": 60,
      "sections": [
        {
          "title": "Tên phần (Ví dụ: READING...)",
          "totalPoints": 0.0,
          "questions": [
            {
              "id": "1",
              "partName": "Reading",
              "type": "multiple-choice",
              "content": "Nội dung đoạn văn bài đọc (nếu là câu đầu tiên của bài) HOẶC nội dung câu hỏi...",
              "options": ["A...", "B...", "C...", "D..."],
              "correctAnswer": "KEY",
              "level": "Thông hiểu"
            }
          ]
        }
      ]
    }
  `;

  try {
    const response = await client.models.generateContent({
      model: MODEL_NAME,
      contents: prompt,
      config: {
        systemInstruction: systemInstruction,
        responseMimeType: "application/json",
      }
    });

    if (response.text) {
        const cleanedText = cleanJsonString(response.text);
        try {
          return JSON.parse(cleanedText) as ExamData;
        } catch (parseError) {
          console.error("JSON Parse Error:", parseError);
          console.log("Raw Response:", response.text);
          throw new Error("Dữ liệu trả về từ AI không đúng định dạng JSON.");
        }
    }
    throw new Error("Failed to generate exam content");
  } catch (error) {
    console.error("Generation Error:", error);
    throw error;
  }
};

import React, { useState, useCallback } from 'react';
import { AppStep, ExamData, AnalysisResult } from './types';
import { analyzeExamFile, generateFullExam } from './services/geminiService';
import ExamPreview from './components/ExamPreview';
import { UploadIcon, FileTextIcon, WandIcon, CheckCircleIcon, ChevronRightIcon } from './components/Icons';

// Default matrix template
const DEFAULT_MATRIX = `I. MULTIPLE CHOICE (8.0 points)
1. Phonetics (4 questions): Pronunciation (2), Stress (2).
2. Lexico-Grammar (6 questions): Tenses, Prepositions, Phrasal verbs, Word choice.
3. Functional Speaking (2 questions): Daily conversation exchanges.
4. Reading Comprehension (5 questions): Read a passage about Environment and answer.
5. Cloze Test (5 questions): Fill in the blanks (Topic: Technology).

II. WRITING (2.0 points)
1. Sentence Transformation (4 questions): Voice, Conditional, Reported speech.
2. Paragraph Writing (1 question): Write a paragraph (100-120 words) about a local festival.`;

const App: React.FC = () => {
  const [currentStep, setCurrentStep] = useState<AppStep>(AppStep.UPLOAD);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Data State
  const [sampleAnalysis, setSampleAnalysis] = useState<AnalysisResult | null>(null);
  const [matrixText, setMatrixText] = useState(DEFAULT_MATRIX);
  const [generatedExam, setGeneratedExam] = useState<ExamData | null>(null);

  // File Upload Handler (Simulated for Demo)
  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setIsLoading(true);
    setError(null);

    try {
      const reader = new FileReader();
      reader.onload = async (e) => {
        const text = e.target?.result as string;
        // Check if text is binary garbage (simple check)
        if (text.substring(0, 100).includes('')) {
             // Mocking analysis for binary files since we don't have mammoth loaded via npm
             const mockAnalysis: AnalysisResult = {
                difficulty: "Trung bình - Khá",
                structureSummary: "Đề gồm 40 câu trắc nghiệm và 2 bài viết tự luận. Tập trung ngữ pháp lớp 9.",
                cefrLevel: "A2-B1",
                readingStats: {
                    avgWordCount: 180,
                    difficultyDesc: "Văn bản chủ đề đời sống, câu ghép chiếm 30%"
                }
             };
             // Simulate network delay
             setTimeout(() => {
                setSampleAnalysis(mockAnalysis);
                setIsLoading(false);
                setCurrentStep(AppStep.MATRIX);
             }, 1500);
        } else {
            // Real analysis via Gemini
            const analysis = await analyzeExamFile(text);
            setSampleAnalysis(analysis);
            setIsLoading(false);
            setCurrentStep(AppStep.MATRIX);
        }
      };
      reader.readAsText(file); // Try reading as text
    } catch (err) {
      setError("Có lỗi khi đọc file. Vui lòng thử lại.");
      setIsLoading(false);
    }
  };

  const handleGenerate = async () => {
    if (!sampleAnalysis) return;
    setIsLoading(true);
    setError(null);

    try {
      const exam = await generateFullExam(matrixText, sampleAnalysis);
      setGeneratedExam(exam);
      setCurrentStep(AppStep.PREVIEW);
    } catch (err: any) {
      console.error(err);
      setError(err.message || "Không thể tạo đề thi. Vui lòng kiểm tra kết nối API và thử lại.");
    } finally {
      setIsLoading(false);
