    // We get the innerHTML of our preview component for WYSIWYG export
    const content = document.getElementById('exam-content')?.innerHTML || "";
    const footer = "</body></html>";
    const sourceHTML = header + content + footer;

    const source = 'data:application/vnd.ms-word;charset=utf-8,' + encodeURIComponent(sourceHTML);
    const fileDownload = document.createElement("a");
    document.body.appendChild(fileDownload);
    fileDownload.href = source;
    fileDownload.download = `De_Thi_Tieng_Anh_10_${new Date().getTime()}.doc`;
    fileDownload.click();
    document.body.removeChild(fileDownload);
  };

  // Render Steps
  const renderStep = () => {
    if (isLoading) {
      return (
        <div className="flex flex-col items-center justify-center py-20 animate-fade-in">
          <div className="w-16 h-16 border-4 border-blue-200 border-t-blue-600 rounded-full animate-spin mb-6"></div>
          <h3 className="text-xl font-semibold text-slate-700">AI đang làm việc...</h3>
          <p className="text-slate-500 mt-2">
             {currentStep === AppStep.UPLOAD ? "Đang phân tích độ dài bài đọc và cấu trúc đề..." : "Đang soạn thảo đề thi..."}
          </p>
        </div>
      );
    }

    switch (currentStep) {
      case AppStep.UPLOAD:
        return (
          <div className="bg-white p-8 rounded-xl shadow-sm border border-slate-200 text-center max-w-2xl mx-auto">
            <div className="bg-blue-50 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-6">
              <UploadIcon className="text-blue-600 w-8 h-8" />
            </div>
            <h2 className="text-2xl font-bold text-slate-800 mb-2">Bước 1: Tải lên đề thi mẫu</h2>
            <p className="text-slate-500 mb-8">
              Hệ thống sẽ phân tích độ khó và cấu trúc đề thi của bạn để làm căn cứ tạo đề mới.
              Hỗ trợ file .docx hoặc .pdf (vui lòng chuyển sang text nếu file ảnh).
            </p>

            <label className="block w-full cursor-pointer group">
              <input type="file" className="hidden" accept=".docx,.txt,.pdf" onChange={handleFileUpload} />
