                  Nhấn để chọn file từ máy tính
                </p>
                <p className="text-xs text-slate-400 mt-2">DOCX, PDF (Max 5MB)</p>
              </div>
            </label>
          </div>
        );

      case AppStep.MATRIX:
        return (
          <div className="bg-white p-8 rounded-xl shadow-sm border border-slate-200 max-w-3xl mx-auto">
