// Initialize Gemini Client
const getClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) throw new Error("API Key not found");
  return new GoogleGenAI({ apiKey });
};

const MODEL_NAME = "gemini-3-flash-preview"; 

// Helper to clean JSON string from Markdown formatting
const cleanJsonString = (str: string) => {
  if (!str) return "";
  let cleaned = str.replace(/^```json\s*/, "").replace(/^```\s*/, "").replace(/\s*```$/, "");
  return cleaned.trim();
};

/**
 * Step 1: Analyze the uploaded exam text
 */
export const analyzeExamFile = async (fileContent: string): Promise<AnalysisResult> => {
  const client = getClient();

  const prompt = `
    Bạn là một chuyên gia giáo dục Tiếng Anh tại Việt Nam. 
    Hãy phân tích nội dung đề thi dưới đây (được trích xuất từ file).

    Nhiệm vụ:
    1. Xác định mức độ khó tổng thể (Dễ/Trung bình/Khá/Khó).
    2. Tóm tắt cấu trúc (Các phần chính, số lượng câu).
    3. Đánh giá khung năng lực ngoại ngữ (CEFR Level ước lượng, ví dụ A2, B1).
    4. PHÂN TÍCH RIÊNG PHẦN ĐỌC HIỂU (READING):
       - Tính toán ước lượng số lượng từ (word count) trung bình của các đoạn văn/bài đọc có trong đề.
       - Mô tả ngắn gọn độ phức tạp của ngữ liệu đọc (ví dụ: Chủ đề quen thuộc, câu đơn giản hay văn bản học thuật, câu ghép phức tạp).

    Trả về định dạng JSON:
    {
      "difficulty": "string",
      "structureSummary": "string",
      "cefrLevel": "string",
      "readingStats": {
        "avgWordCount": number, // Ví dụ: 150
        "difficultyDesc": "string" // Ví dụ: "Văn bản thông tin, từ vựng chủ đề môi trường, câu phức trung bình"
      }
    }

    Nội dung đề thi:
    ${fileContent.substring(0, 15000)} 
  `;

  try {
    const response = await client.models.generateContent({
      model: MODEL_NAME,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
      }
    });

    if (response.text) {
      const cleanedText = cleanJsonString(response.text);
      return JSON.parse(cleanedText);
    }
    throw new Error("No response text");
  } catch (error) {
    console.error("Error analyzing exam:", error);
    return {
      difficulty: "Chưa xác định",
      structureSummary: "Không thể phân tích cấu trúc",
      cefrLevel: "N/A",
      readingStats: {
        avgWordCount: 150, // Default fallback
        difficultyDesc: "Trung bình"
      }
    };
  }
};

/**
 * Step 3: Generate the full exam based on matrix and analysis
 */
export const generateFullExam = async (
  matrixText: string,
  analysisData: AnalysisResult
): Promise<ExamData> => {
  const client = getClient();

  const systemInstruction = `
    Bạn là chuyên gia soạn đề thi Tiếng Anh tuyển sinh vào lớp 10 THPT tại Việt Nam.
    Bạn nắm vững chương trình GDPT 2018 (Sách Global Success, Friends Plus...).

    Yêu cầu quan trọng:
    - Nội dung: 85% kiến thức lớp 9, 10% lớp 8, 5% nâng cao.
    - Không trùng lặp câu hỏi cũ.
    - Ngôn ngữ: Tiếng Anh chuẩn mực.
  `;

  const prompt = `
    Hãy tạo một đề thi hoàn chỉnh dựa trên MA TRẬN và CÁC RÀNG BUỘC sau đây.

    1. ĐỘ KHÓ MỤC TIÊU: ${analysisData.difficulty} (Tương đương ${analysisData.cefrLevel}).

    2. RÀNG BUỘC PHẦN ĐỌC HIỂU (READING) - BẮT BUỘC TUÂN THỦ:
       - ĐỘ DÀI: Các bài đọc phải có độ dài khoảng ${analysisData.readingStats.avgWordCount} từ/bài (Chấp nhận sai số ±10%). 
       - NGỮ LIỆU: Sử dụng ngữ liệu có độ khó tương đương mô tả: "${analysisData.readingStats.difficultyDesc}".
       - CHỦ ĐỀ: Nằm trong chương trình SGK Tiếng Anh 9 mới (Global Success, Friends Plus...).
       - LƯU Ý: Nếu ma trận yêu cầu 2 bài đọc, cả 2 bài phải tuân thủ độ dài này.

    3. QUY ĐỊNH ĐỊNH DẠNG ĐẶC BIỆT CHO DẠNG BÀI HỘI THOẠI (GAP-FILL CONVERSATION):
       - Nếu ma trận có dạng bài "Read the conversation and choose the correct letter...", hãy tạo ra MỘT câu hỏi duy nhất (Question object) đại diện cho cả bài.
       - Type: "conversation-matching"
       - Content: Chứa toàn bộ đoạn hội thoại, giữ nguyên các vị trí điền khuyết (ví dụ (11), (12)...).
       - Options: Chứa danh sách các câu trả lời (A, B, C, D, E, F, G...) để học sinh chọn.

    4. MA TRẬN ĐỀ THI:
    ${matrixText}

    5. YÊU CẦU ĐẦU RA (JSON):
    Trả về JSON cấu trúc như sau (KHÔNG thêm markdown block):
    {
      "title": "KỲ THI TUYỂN SINH VÀO LỚP 10 THPT",
      "subtitle": "MÔN: TIẾNG ANH - NĂM HỌC 2024-2025",
      "duration": 60,
      "sections": [
        {
          "title": "Tên phần (Ví dụ: READING...)",
          "totalPoints": 0.0,
          "questions": [
            {
              "id": "1",
              "partName": "Reading",
              "type": "multiple-choice" | "conversation-matching",
              "content": "Nội dung...",
              "options": ["A...", "B..."],
              "correctAnswer": "KEY",
              "level": "Thông hiểu"
            }
          ]
        }
      ]
    }
  `;

  try {
    const response = await client.models.generateContent({
      model: MODEL_NAME,
      contents: prompt,
      config: {
        systemInstruction: systemInstruction,
        responseMimeType: "application/json",
      }
    });

    if (response.text) {
        const cleanedText = cleanJsonString(response.text);
        try {
          return JSON.parse(cleanedText) as ExamData;
        } catch (parseError) {
          console.error("JSON Parse Error:", parseError);
          console.log("Raw Response:", response.text);
          throw new Error("Dữ liệu trả về từ AI không đúng định dạng JSON.");
        }
    }
    throw new Error("Failed to generate exam content");
  } catch (error) {
    console.error("Generation Error:", error);
    throw error;
  }
};

import React, { useState } from 'react';
import { ExamData, ExamSection, Question } from '../types';
import { DownloadIcon, EditIcon } from './Icons';

interface Props {
  data: ExamData;
  onExport: () => void;
}

const ExamPreview: React.FC<Props> = ({ data, onExport }) => {
  // Simple state to allow "editing" - in a real app this would update the deep structure
  // For demo, we just toggle an edit mode visualization
  const [editingId, setEditingId] = useState<string | null>(null);

  const handleEditClick = (id: string) => {
    setEditingId(editingId === id ? null : id);
  };

  const getOptionLabel = (index: number) => {
    return String.fromCharCode(65 + index); // 65 is 'A'
  };

  const renderQuestionContent = (q: Question, index: number) => {
    // Special rendering for Conversation Matching (Gap-fill) type
    if (q.type === 'conversation-matching') {
      return (
        <div className="relative group p-1 rounded hover:bg-gray-50 transition-colors">
            <div className="flex items-start gap-2">
                {/* We don't necessarily need "Question X" label for the whole block if the instruction is inside, 
                    but to keep consistency we show it or maybe hide it based on preference. 
                    Given the user requirement "Question" bold, we keep the structure but format content differently. */}
                <div className="flex-1">
                   {/* 1. The Dialogue/Instructions Content */}
                    <div 
                        className={`text-gray-900 whitespace-pre-line ${editingId === q.id ? 'border border-blue-400 p-2 rounded bg-white' : ''}`}
                        contentEditable={editingId === q.id}
                        suppressContentEditableWarning
                        style={{ fontSize: '12pt', lineHeight: '1.5' }}
                    >
                        {/* We manually prepend Question label if needed, or rely on the content having it. 
                            However, usually this type corresponds to a range of questions (e.g. 11-15).
                            We render the content directly as it usually contains the prompt text. */}
                        <span className="font-bold mr-2" style={{ fontWeight: 'bold' }}>Question {index + 1}:</span>
                        {q.content}
                    </div>

                    {/* 2. The Boxed Options (A, B, C, D...) */}
                    {q.options && (
                        <div 
                            className="mt-4 border border-black p-4" 
                            style={{ border: '1px solid black', padding: '15px', marginTop: '15px' }}
                        >
                            <div className="flex flex-col gap-1" style={{ fontSize: '12pt' }}>
                                {q.options.map((opt, oIdx) => {
                                    // Helper to detect if the option string already has "A." or not. 
                                    // If AI provides "A. Not always", we just render it. If "Not always", we add "A."
                                    const label = getOptionLabel(oIdx);
                                    const text = opt.trim().match(/^[A-H]\./) ? opt : `${label}. ${opt}`;

                                    return (
                                        <div key={oIdx} className={`${editingId === q.id ? 'border border-blue-200 p-1' : ''}`}>
                                            {text}
                                        </div>
                                    );
                                })}
                            </div>
                        </div>
                    )}
                </div>

                 {/* Edit Button */}
                 <button 
                    onClick={() => handleEditClick(q.id)}
                    className="opacity-0 group-hover:opacity-100 p-1 text-gray-500 hover:text-blue-600 transition-opacity absolute right-0 top-0"
                    title="Chỉnh sửa"
                >
                    <EditIcon className="w-4 h-4" />
                </button>
            </div>
        </div>
      );
    }

    // Default Rendering for Multiple Choice / Essay
    return (
      <div key={q.id} className="relative group p-1 rounded hover:bg-gray-50 transition-colors">
        <div className="flex items-start gap-2">
          <span className="font-bold whitespace-nowrap" style={{ fontSize: '12pt', fontWeight: 'bold' }}>Question {index + 1}:</span>
          <div className="flex-1">
            <div 
              className={`text-gray-900 ${editingId === q.id ? 'border border-blue-400 p-2 rounded bg-white' : ''}`}
              contentEditable={editingId === q.id}
              suppressContentEditableWarning
              style={{ fontSize: '12pt', lineHeight: '1.5' }}
            >
              {q.content}
            </div>

            {/* Options */}
            {q.options && (
              <div className="grid grid-cols-2 gap-x-8 gap-y-2 mt-1 ml-4" style={{ fontSize: '12pt' }}>
                {q.options.map((opt, oIdx) => (
                  <div key={oIdx} className={`${editingId === q.id ? 'border border-blue-200 p-1' : ''}`}>
                    {opt}
                  </div>
                ))}
              </div>
            )}
          </div>

          {/* Edit Button */}
          <button 
            onClick={() => handleEditClick(q.id)}
            className="opacity-0 group-hover:opacity-100 p-1 text-gray-500 hover:text-blue-600 transition-opacity"
            title="Chỉnh sửa"
          >
            <EditIcon className="w-4 h-4" />
          </button>
        </div>
      </div>
    );
  };

  return (
    <div className="w-full max-w-4xl mx-auto bg-white shadow-xl rounded-lg overflow-hidden min-h-screen flex flex-col">
      {/* Toolbar */}
      <div className="bg-slate-800 text-white p-4 flex justify-between items-center sticky top-0 z-10">
        <div>
          <h2 className="text-lg font-bold">Xem trước đề thi</h2>
          <p className="text-xs text-slate-300">Nhấn vào câu hỏi để chỉnh sửa (demo)</p>
        </div>
        <button 
          onClick={onExport}
          className="bg-blue-600 hover:bg-blue-500 text-white px-4 py-2 rounded-md flex items-center gap-2 transition-colors font-medium shadow-sm"
        >
          <DownloadIcon className="w-4 h-4" />
          Tải về DOCX
        </button>
      </div>

      {/* Exam Content - Mimicking Word Document Look */}
      <div className="p-8 md:p-12 overflow-y-auto flex-1 bg-white font-serif" id="exam-content">

        {/* Header - Table Layout for Word Compatibility */}
        <table style={{ width: '100%', borderCollapse: 'collapse', marginBottom: '10px' }}>
          <tbody>
            <tr>
              {/* Left Column */}
              <td style={{ width: '30%', verticalAlign: 'top', textAlign: 'center', paddingRight: '5px' }}>
                <p style={{ margin: 0, fontWeight: 'bold', fontSize: '11pt', textTransform: 'uppercase' }}>SỞ GIÁO DỤC VÀ ĐÀO TẠO</p>
                <p style={{ margin: 0, fontWeight: 'bold', fontSize: '11pt' }}>ĐỀ THI THAM KHẢO</p>
              </td>

              {/* Center Column */}
              <td style={{ width: '40%', verticalAlign: 'top', textAlign: 'center' }}>
                <p style={{ margin: 0, fontWeight: 'bold', fontSize: '13pt', textTransform: 'uppercase' }}>KỲ THI TUYỂN SINH</p>
                <p style={{ margin: 0, fontWeight: 'bold', fontSize: '13pt', textTransform: 'uppercase' }}>VÀO LỚP 10 THPT</p>
                <p style={{ margin: '5px 0 0 0', fontWeight: 'bold', fontSize: '12pt', textTransform: 'uppercase' }}>MÔN: TIẾNG ANH</p>
                <p style={{ margin: 0, fontWeight: 'bold', fontSize: '12pt', textTransform: 'uppercase' }}>NĂM HỌC 2024 - 2025</p>
                <p style={{ margin: '5px 0 0 0', fontStyle: 'italic', fontSize: '11pt' }}>Thời gian làm bài: {data.duration} phút</p>
              </td>

              {/* Right Column - Score Box */}
              <td style={{ width: '30%', verticalAlign: 'top', paddingLeft: '5px' }}>
                <div style={{ border: '1px solid black', padding: '5px', height: '80px', fontSize: '11pt' }}>
                   <p style={{ margin: '5px 0 15px 0' }}>Mã phách: ........................</p>
                   <p style={{ margin: 0 }}>Điểm: ..............................</p>
                </div>
              </td>
            </tr>
          </tbody>
        </table>

        {/* Divider Line */}
        <div style={{ borderBottom: '2px solid black', marginBottom: '25px' }}></div>

        {/* Sections */}
        <div className="space-y-6">
          {data.sections.map((section, sIdx) => (
            <div key={sIdx} className="mb-6">
              <h3 className="font-bold text-lg mb-2 uppercase" style={{ fontSize: '12pt', textDecoration: 'underline' }}>
                {section.title}
              </h3>

              <div className="space-y-3">
                {section.questions.map((q, qIdx) => renderQuestionContent(q, qIdx))}
              </div>
            </div>
          ))}
        </div>

        <div className="mt-12 text-center text-sm italic text-gray-500">
          --- HẾT ---
        </div>
      </div>
    </div>
  );
};

