}

export interface MatrixData {
  rawText: string;
  parsed?: any;
}

import { GoogleGenAI, Type } from "@google/genai";
import { ExamData, AnalysisResult } from "../types";

// Initialize Gemini Client
const getClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) throw new Error("API Key not found");
  return new GoogleGenAI({ apiKey });
};

const MODEL_NAME = "gemini-3-flash-preview"; 

// Helper to clean JSON string from Markdown formatting
const cleanJsonString = (str: string) => {
  if (!str) return "";
  let cleaned = str.replace(/^```json\s*/, "").replace(/^```\s*/, "").replace(/\s*```$/, "");
  return cleaned.trim();
};

/**
 * Step 1: Analyze the uploaded exam text
 */
export const analyzeExamFile = async (fileContent: string): Promise<AnalysisResult> => {
  const client = getClient();

  const prompt = `
    Bạn là một chuyên gia giáo dục Tiếng Anh tại Việt Nam. 
    Hãy phân tích nội dung đề thi dưới đây (được trích xuất từ file).

    Nhiệm vụ:
    1. Xác định mức độ khó tổng thể (Dễ/Trung bình/Khá/Khó).
    2. Tóm tắt cấu trúc (Các phần chính, số lượng câu).
    3. Đánh giá khung năng lực ngoại ngữ (CEFR Level ước lượng, ví dụ A2, B1).
    4. PHÂN TÍCH RIÊNG PHẦN ĐỌC HIỂU (READING):
       - Tính toán ước lượng số lượng từ (word count) trung bình của các đoạn văn/bài đọc có trong đề.
       - Mô tả ngắn gọn độ phức tạp của ngữ liệu đọc (ví dụ: Chủ đề quen thuộc, câu đơn giản hay văn bản học thuật, câu ghép phức tạp).

    Trả về định dạng JSON:
    {
      "difficulty": "string",
      "structureSummary": "string",
      "cefrLevel": "string",
      "readingStats": {
        "avgWordCount": number, // Ví dụ: 150
        "difficultyDesc": "string" // Ví dụ: "Văn bản thông tin, từ vựng chủ đề môi trường, câu phức trung bình"
      }
    }

    Nội dung đề thi:
    ${fileContent.substring(0, 15000)} 
  `;

  try {
    const response = await client.models.generateContent({
      model: MODEL_NAME,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
      }
    });

    if (response.text) {
      const cleanedText = cleanJsonString(response.text);
      return JSON.parse(cleanedText);
    }
    throw new Error("No response text");
  } catch (error) {
    console.error("Error analyzing exam:", error);
    return {
      difficulty: "Chưa xác định",
      structureSummary: "Không thể phân tích cấu trúc",
      cefrLevel: "N/A",
      readingStats: {
        avgWordCount: 150, // Default fallback
        difficultyDesc: "Trung bình"
      }
    };
  }
};

/**
 * Step 3: Generate the full exam based on matrix and analysis
 */
export const generateFullExam = async (
  matrixText: string,
  analysisData: AnalysisResult
): Promise<ExamData> => {
  const client = getClient();

  const systemInstruction = `
    Bạn là chuyên gia soạn đề thi Tiếng Anh tuyển sinh vào lớp 10 THPT tại Việt Nam.
    Bạn nắm vững chương trình GDPT 2018 (Sách Global Success, Friends Plus...).

    Yêu cầu quan trọng:
    - Nội dung: 85% kiến thức lớp 9, 10% lớp 8, 5% nâng cao.
    - Không trùng lặp câu hỏi cũ.
    - Ngôn ngữ: Tiếng Anh chuẩn mực.
  `;

  const prompt = `
    Hãy tạo một đề thi hoàn chỉnh dựa trên MA TRẬN và CÁC RÀNG BUỘC sau đây.

    1. ĐỘ KHÓ MỤC TIÊU: ${analysisData.difficulty} (Tương đương ${analysisData.cefrLevel}).

    2. RÀNG BUỘC PHẦN ĐỌC HIỂU (READING) - BẮT BUỘC TUÂN THỦ:
       - ĐỘ DÀI: Các bài đọc phải có độ dài khoảng ${analysisData.readingStats.avgWordCount} từ/bài (Chấp nhận sai số ±10%). 
       - NGỮ LIỆU: Sử dụng ngữ liệu có độ khó tương đương mô tả: "${analysisData.readingStats.difficultyDesc}".
       - CHỦ ĐỀ: Nằm trong chương trình SGK Tiếng Anh 9 mới (Global Success, Friends Plus...).
       - LƯU Ý: Nếu ma trận yêu cầu 2 bài đọc, cả 2 bài phải tuân thủ độ dài này.

    3. CẤU TRÚC JSON CHO BÀI ĐỌC (READING/CLOZE TEST):
       - NỘI DUNG ĐOẠN VĂN: Phải đặt trong trường "passageContent" của đối tượng Section. Tuyệt đối không đặt đoạn văn vào nội dung câu hỏi (Questions).
       - CÁC CÂU HỎI: Nằm trong mảng "questions" như bình thường.
       - Với Cloze Test (điền từ): Đoạn văn chứa các chỗ trống đánh số (1), (2)... nằm trong "passageContent". Các câu hỏi trắc nghiệm tương ứng nằm trong "questions".

    4. QUY ĐỊNH ĐỊNH DẠNG ĐẶC BIỆT CHO DẠNG BÀI HỘI THOẠI (GAP-FILL CONVERSATION):
       - Nếu ma trận có dạng bài "Read the conversation and choose the correct letter...", hãy tạo ra MỘT câu hỏi duy nhất (Question object) đại diện cho cả bài.
       - Type: "conversation-matching"
       - Content: Chứa toàn bộ đoạn hội thoại, với các vị trí điền khuyết dạng (1), (2), (3)...
       - Options: Chứa danh sách các câu trả lời (A, B, C, D, E, F, G...).
       - questionCount: Bắt buộc phải có trường này, giá trị là số lượng ô trống cần điền (ví dụ: 5).
       - correctAnswer: Liệt kê đáp án theo thứ tự, ví dụ: "1-A, 2-C, 3-D...".

    5. MA TRẬN ĐỀ THI:
    ${matrixText}

    6. YÊU CẦU QUAN TRỌNG VỀ TIÊU ĐỀ PHẦN (Sections Title):
       - Field "title" trong mảng "sections" PHẢI chứa đầy đủ tên phần và hướng dẫn làm bài (Instruction).
       - Định dạng bắt buộc: "Part [số]. [Hướng dẫn chi tiết]". 
       - Ví dụ đúng: "Part 1. Choose the letter (A, B, C or D) to indicate the correct answer to each of the following questions."

    7. YÊU CẦU ĐẦU RA (JSON):
    Trả về JSON cấu trúc như sau (KHÔNG thêm markdown block):
    {
      "title": "KỲ THI TUYỂN SINH VÀO LỚP 10 THPT",
      "subtitle": "MÔN: TIẾNG ANH - NĂM HỌC 2024-2025",
      "duration": 60,
      "sections": [
        {
          "title": "Part 1. Choose the letter...",
          "totalPoints": 0.0,
          "questions": [...]
        },
        {
          "title": "Part 5. Read the following passage...",
          "passageContent": "Plastic pollution is one of the most serious... (Nội dung đoạn văn ở đây)",
          "totalPoints": 0.0,
          "questions": [
            {
              "id": "13",
              "partName": "Reading",
              "type": "multiple-choice",
              "content": "What is the main topic of the passage?",
              "options": ["A...", "B..."],
              "correctAnswer": "C",
              "level": "Thông hiểu"
            }
          ]
        }
      ]
    }
  `;

  try {
    const response = await client.models.generateContent({
      model: MODEL_NAME,
      contents: prompt,
      config: {
        systemInstruction: systemInstruction,
        responseMimeType: "application/json",
      }
    });

    if (response.text) {
        const cleanedText = cleanJsonString(response.text);
        try {
          return JSON.parse(cleanedText) as ExamData;
        } catch (parseError) {
          console.error("JSON Parse Error:", parseError);
          console.log("Raw Response:", response.text);
          throw new Error("Dữ liệu trả về từ AI không đúng định dạng JSON.");
        }
    }
    throw new Error("Failed to generate exam content");
  } catch (error) {
    console.error("Generation Error:", error);
    throw error;
  }
};

import React, { useState, useMemo } from 'react';
import { ExamData, ExamSection, Question } from '../types';
import { DownloadIcon, EditIcon } from './Icons';

interface Props {
  data: ExamData;
  onExport: () => void;
}

const ExamPreview: React.FC<Props> = ({ data, onExport }) => {
  // Simple state to allow "editing" - in a real app this would update the deep structure
  const [editingId, setEditingId] = useState<string | null>(null);

  const handleEditClick = (id: string) => {
    setEditingId(editingId === id ? null : id);
  };

  const getOptionLabel = (index: number) => {
    return String.fromCharCode(65 + index); // 65 is 'A'
  };

  // Pre-calculate start numbers for all questions to ensure continuous numbering across sections
  const questionNumberMap = useMemo(() => {
    const map = new Map<string, number>();
    let counter = 1;

    data.sections.forEach(section => {
      section.questions.forEach(q => {
        map.set(q.id, counter);
        // If questionCount is not provided by AI, try to infer from content regex match for conversation type, else default to 1
        let increment = q.questionCount || 1;
        if (q.type === 'conversation-matching' && !q.questionCount) {
             const matches = q.content.match(/\(\d+\)/g);
             increment = matches ? matches.length : 1; 
        }
        counter += increment;
      });
    });
    return map;
  }, [data]);

  const renderQuestionContent = (q: Question) => {
    const startNumber = questionNumberMap.get(q.id) || 1;

    // Special rendering for Conversation Matching (Gap-fill) type
    if (q.type === 'conversation-matching') {

      // Dynamic replacement of numbers in content (e.g., (1) -> (11)) to match global exam numbering
      let contentWithCorrectNumbers = q.content;
      let gapCounter = 0;
      // Replace (number) pattern with incrementing global numbers
      contentWithCorrectNumbers = contentWithCorrectNumbers.replace(/\(\d+\)/g, () => {
          const num = startNumber + gapCounter;
          gapCounter++;
          return `(${num})`;
      });

      return (
        <div key={q.id} className="relative group p-2 rounded hover:bg-gray-50 transition-colors">
            <div className="flex items-start gap-3">
                <div className="flex-1">
                   {/* 1. The Dialogue/Instructions Content */}
                    <div 
                        className={`text-black whitespace-pre-line ${editingId === q.id ? 'border-2 border-[#0077b5] p-3 rounded bg-white shadow-sm' : ''}`}
                        contentEditable={editingId === q.id}
                        suppressContentEditableWarning
                        style={{ fontSize: '13pt', lineHeight: '1.6', fontFamily: '"Times New Roman", Times, serif' }}
                    >
                        {/* We use the start number for the block label */}
                        <span className="font-bold mr-2" style={{ fontWeight: 'bold' }}>Question {startNumber}:</span>
                        {editingId === q.id ? q.content : contentWithCorrectNumbers}
                    </div>

                    {/* 2. The Boxed Options (A, B, C, D...) */}
                    {q.options && (
                        <div 
                            className="mt-5 border border-black p-5" 
                            style={{ border: '1px solid black', padding: '15px', marginTop: '20px' }}
                        >
                            <div className="flex flex-col gap-2" style={{ fontSize: '13pt', fontFamily: '"Times New Roman", Times, serif' }}>
                                {q.options.map((opt, oIdx) => {
                                    const label = getOptionLabel(oIdx);
                                    // Handle cases where AI might already include "A."
                                    const text = opt.trim().match(/^[A-H]\./) ? opt : `${label}. ${opt}`;

                                    return (
                                        <div key={oIdx} className={`${editingId === q.id ? 'border border-[#0077b5] p-1 bg-blue-50' : ''}`}>
                                            {text}
                                        </div>
                                    );
                                })}
                            </div>
                        </div>
                    )}
                </div>

                 {/* Edit Button */}
                 <button 
                    onClick={() => handleEditClick(q.id)}
                    className="opacity-0 group-hover:opacity-100 p-2 text-gray-400 hover:text-[#0077b5] transition-opacity absolute right-0 top-0 bg-white rounded-full shadow-sm border border-gray-200"
                    title="Chỉnh sửa nội dung"
                >
                    <EditIcon className="w-5 h-5" />
                </button>
            </div>
        </div>
      );
    }

    // Default Rendering for Multiple Choice / Essay
    return (
      <div key={q.id} className="relative group p-2 rounded hover:bg-gray-50 transition-colors">
        <div className="flex items-start gap-3">
          <span className="font-bold whitespace-nowrap pt-1" style={{ fontSize: '13pt', fontWeight: 'bold', fontFamily: '"Times New Roman", Times, serif' }}>Question {startNumber}:</span>
          <div className="flex-1">
            <div 
              className={`text-black ${editingId === q.id ? 'border-2 border-[#0077b5] p-3 rounded bg-white shadow-sm' : ''}`}
              contentEditable={editingId === q.id}
              suppressContentEditableWarning
              style={{ fontSize: '13pt', lineHeight: '1.6', fontFamily: '"Times New Roman", Times, serif' }}
            >
              {q.content}
            </div>

            {/* Options */}
            {q.options && (
              <div className="grid grid-cols-2 gap-x-12 gap-y-3 mt-2 ml-4" style={{ fontSize: '13pt', fontFamily: '"Times New Roman", Times, serif' }}>
                {q.options.map((opt, oIdx) => (
                  <div key={oIdx} className={`${editingId === q.id ? 'border border-[#0077b5] p-1 bg-blue-50' : ''}`}>
                    {opt}
                  </div>
                ))}
              </div>
            )}
          </div>

          {/* Edit Button */}
          <button 
            onClick={() => handleEditClick(q.id)}
            className="opacity-0 group-hover:opacity-100 p-2 text-gray-400 hover:text-[#0077b5] transition-opacity absolute right-0 top-0 bg-white rounded-full shadow-sm border border-gray-200"
            title="Chỉnh sửa nội dung"
          >
            <EditIcon className="w-5 h-5" />
          </button>
        </div>
      </div>
    );
  };

  return (
    <div className="w-full max-w-5xl mx-auto bg-white shadow-2xl rounded-xl overflow-hidden min-h-screen flex flex-col border border-gray-200 animate-fade-in">
      {/* Toolbar */}
      <div className="bg-[#0077b5] text-white p-5 flex justify-between items-center sticky top-0 z-10 shadow-md">
        <div>
          <h2 className="text-xl font-bold flex items-center gap-2">
             <span className="bg-white/20 p-1 rounded">DOC</span> Xem trước đề thi
          </h2>
          <p className="text-sm text-blue-100 mt-1 opacity-90">Chế độ xem trước khổ A4 - Nhấn vào nội dung để chỉnh sửa nhanh</p>
        </div>
        <button 
          onClick={onExport}
          className="bg-white text-[#0077b5] hover:bg-gray-100 px-6 py-2.5 rounded-lg flex items-center gap-2 transition-all font-bold shadow-sm hover:shadow-md transform active:scale-95"
        >
          <DownloadIcon className="w-5 h-5" />
          Tải về DOCX
        </button>
      </div>

      {/* Exam Content - Mimicking Word Document Look - A4 Scaling */}
      <div className="p-16 overflow-y-auto flex-1 bg-white" id="exam-content" style={{ fontFamily: '"Times New Roman", Times, serif' }}>

        {/* Header - Table Layout for Word Compatibility */}
        <table style={{ width: '100%', borderCollapse: 'collapse', marginBottom: '20px' }}>
          <tbody>
            <tr>
              {/* Left Column */}
