      </div>

      {/* Exam Content - Mimicking Word Document Look - A4 Scaling */}
      <div className="p-16 overflow-y-auto flex-1 bg-white" id="exam-content" style={{ fontFamily: '"Times New Roman", Times, serif' }}>

        {/* Header - Table Layout for Word Compatibility */}
        <table style={{ width: '100%', borderCollapse: 'collapse', marginBottom: '20px' }}>
          <tbody>
            <tr>
              {/* Left Column */}
              <td style={{ width: '30%', verticalAlign: 'top', textAlign: 'center', paddingRight: '10px' }}>
                <p style={{ margin: 0, fontWeight: 'bold', fontSize: '12pt', textTransform: 'uppercase' }}>SỞ GIÁO DỤC VÀ ĐÀO TẠO</p>
                <p style={{ margin: 0, fontWeight: 'bold', fontSize: '12pt' }}>ĐỀ THI THAM KHẢO</p>
              </td>

              {/* Center Column */}
              <td style={{ width: '40%', verticalAlign: 'top', textAlign: 'center' }}>
                <p style={{ margin: 0, fontWeight: 'bold', fontSize: '14pt', textTransform: 'uppercase' }}>KỲ THI TUYỂN SINH</p>
